/**
 * bundle.js — flattens src/ into two files that can be pasted into the Apps
 * Script editor by hand.
 *
 * The modular sources stay the thing you edit; this is the shape you deploy when
 * installing clasp is not an option. Run it after any change to src/:
 *
 *   node tools/bundle.js
 *
 * Produces dist/Code.gs, dist/main.html and dist/appsscript.json.
 */

'use strict';
const fs = require('fs');
const path = require('path');

const SRC = path.join(__dirname, '..', 'src');
const DIST = path.join(__dirname, '..', 'dist');

// Config first: it declares the constants the other files close over at load
// time. The rest is alphabetical so the output is stable between runs.
const ORDER = [
  'Config.gs', 'Repo.gs', 'Auth.gs', 'Warranty.gs', 'Audit.gs', 'Files.gs',
  'Mailer.gs', 'Claims.gs', 'MasterData.gs', 'Export.gs', 'Triggers.gs',
  'Setup.gs', 'Code.gs'
];

function read(file) {
  return fs.readFileSync(path.join(SRC, file), 'utf8');
}

function banner(title, note) {
  const line = '='.repeat(74);
  return [
    '/* ' + line,
    ' * ' + title,
    note ? ' *' : null,
    note ? note.split('\n').map(function (l) { return l ? ' * ' + l : ' *'; }).join('\n') : null,
    ' * ' + line + ' */',
    ''
  ].filter(function (l) { return l !== null; }).join('\n');
}

/* ------------------------------------------------------------- Code.gs */

const present = fs.readdirSync(SRC).filter(function (f) { return /\.gs$/.test(f); });
const missing = present.filter(function (f) { return ORDER.indexOf(f) === -1; });
if (missing.length) {
  console.error('These files are not in the bundle order and would be dropped: ' + missing.join(', '));
  process.exit(1);
}

const generated = new Date().toISOString().slice(0, 10);

let code = banner(
  'Warranty Claim Portal — bundled server code',
  'Generated by tools/bundle.js on ' + generated + '. Do not edit this file:\n' +
  'change the matching file in src/ and run the bundler again.\n\n' +
  'Paste this as a single script file named "Code.gs", and dist/main.html as an\n' +
  'HTML file named "main".'
);

ORDER.forEach(function (file) {
  code += '\n' + banner(file) + '\n' + read(file).trim() + '\n';
});

// The bundled HTML file is called "main"; the modular version calls it "index".
code = code.replace("createTemplateFromFile('index')", "createTemplateFromFile('main')");

/* ----------------------------------------------------------- main.html */

const styles = read('Styles.html').trim();
const script = read('Script.html').trim();

let page = read('index.html')
  .replace(/[ \t]*<\?!= include\('Styles'\); \?>/, styles)
  .replace(/[ \t]*<\?!= include\('Script'\); \?>/, script);

if (/<\?!=/.test(page)) {
  console.error('An include scriptlet was left unresolved in index.html.');
  process.exit(1);
}

page = page.replace('<head>',
  '<head>\n  <!-- Generated by tools/bundle.js on ' + generated + '. Edit src/index.html,\n' +
  '       src/Styles.html or src/Script.html instead, then run the bundler again. -->');

/* -------------------------------------------------------------- write */

fs.mkdirSync(DIST, { recursive: true });
fs.writeFileSync(path.join(DIST, 'Code.gs'), code);
fs.writeFileSync(path.join(DIST, 'main.html'), page);
fs.copyFileSync(path.join(SRC, 'appsscript.json'), path.join(DIST, 'appsscript.json'));

const kb = function (s) { return (s.length / 1024).toFixed(0) + ' KB'; };
console.log('');
console.log('  dist/Code.gs          ' + ORDER.length + ' source files, ' + kb(code));
console.log('  dist/main.html        page, styles and client script, ' + kb(page));
console.log('  dist/appsscript.json  manifest');
console.log('');
